package java.nio;
public class ByteBuffer extends Buffer implements Comparable<ByteBuffer> {
    protected final byte[] data; protected final int offset; protected boolean readOnly; protected ByteOrder order=ByteOrder.BIG_ENDIAN;
    protected ByteBuffer(byte[] data,int offset,int capacity){super(capacity);this.data=data;this.offset=offset;}
    public static ByteBuffer allocate(int capacity){return new ByteBuffer(new byte[capacity],0,capacity);} public static ByteBuffer allocateDirect(int capacity){return allocate(capacity);} public static ByteBuffer wrap(byte[] data){return new ByteBuffer(data,0,data.length);} public static ByteBuffer wrap(byte[] data,int offset,int length){ByteBuffer b=wrap(data);b.position(offset);b.limit(offset+length);return b;}
    public boolean isReadOnly(){return readOnly;} public boolean isDirect(){return false;} public boolean hasArray(){return !readOnly;} public byte[] array(){if(readOnly)throw new UnsupportedOperationException();return data;} public int arrayOffset(){return offset;} public ByteOrder order(){return order;} public ByteBuffer order(ByteOrder o){if(o==null)throw new NullPointerException();order=o;return this;}
    private void check(int index,int length){if(index<0||index+length>limit)throw new IndexOutOfBoundsException();} public byte get(){byte v=get(position);position++;return v;} public byte get(int index){check(index,1);return data[offset+index];} public ByteBuffer get(byte[] out){return get(out,0,out.length);} public ByteBuffer get(byte[] out,int start,int length){check(position,length);System.arraycopy(data,offset+position,out,start,length);position+=length;return this;}
    public ByteBuffer put(byte value){put(position,value);position++;return this;} public ByteBuffer put(int index,byte value){if(readOnly)throw new UnsupportedOperationException();check(index,1);data[offset+index]=value;return this;} public ByteBuffer put(byte[] src){return put(src,0,src.length);} public ByteBuffer put(byte[] src,int start,int length){if(readOnly)throw new UnsupportedOperationException();check(position,length);System.arraycopy(src,start,data,offset+position,length);position+=length;return this;}
    private long read(int index,int n){check(index,n);long v=0;for(int i=0;i<n;i++){int k=order==ByteOrder.BIG_ENDIAN?i:n-1-i;v=(v<<8)|(data[offset+index+k]&255);}return v;} private void write(int index,long v,int n){if(readOnly)throw new UnsupportedOperationException();check(index,n);for(int i=0;i<n;i++){int k=order==ByteOrder.BIG_ENDIAN?n-1-i:i;data[offset+index+k]=(byte)(v>>>(8*i));}}
    public int getInt(){int v=getInt(position);position+=4;return v;} public int getInt(int i){return (int)read(i,4);} public long getLong(){long v=read(position,8);position+=8;return v;} public short getShort(int i){return (short)read(i,2);} public short getShort(){short v=(short)read(position,2);position+=2;return v;} public ByteBuffer putInt(int v){write(position,v,4);position+=4;return this;} public ByteBuffer putLong(long v){write(position,v,8);position+=8;return this;} public ByteBuffer putShort(short v){write(position,v,2);position+=2;return this;}
    public ByteBuffer slice(){ByteBuffer b=new ByteBuffer(data,offset+position,remaining());b.readOnly=readOnly;return b;} public ByteBuffer duplicate(){ByteBuffer b=new ByteBuffer(data,offset,capacity);b.position=position;b.limit=limit;b.readOnly=readOnly;b.order=order;return b;} public ByteBuffer asReadOnlyBuffer(){ByteBuffer b=duplicate();b.readOnly=true;return b;} public int compareTo(ByteBuffer b){int n=Math.min(remaining(),b.remaining());for(int i=0;i<n;i++){int d=get(position+i)-b.get(b.position+i);if(d!=0)return d;}return remaining()-b.remaining();}
}
